// In C++11, only a single return statement is allowed.
// Logic requires recursion and the ternary operator.
constexpr int pow_cpp11(int base, int exp) noexcept
{
  return (exp == 0 ? 1 : base * pow_cpp11(base, exp - 1));
}

// In C++14, imperative code with loops and local variables is permitted.
constexpr int pow_cpp14(int base, int exp) noexcept
{
  auto result = 1;
  for (int i = 0; i < exp; ++i) result *= base;
  return result;
}
